import jwt
from jwt import PyJWTError
import datetime

def verify_jwt_token(token: str, public_key: str) -> dict:
    try:
        unverified_header = jwt.get_unverified_header(token)
    except Exception as e:
        raise ValueError("Invalid token header") from e

    alg = unverified_header.get('alg')
    if alg not in ('RS256', 'ES256'):
        raise ValueError(f"Unsupported algorithm: {alg}")

    try:
        payload = jwt.decode(
            token,
            public_key,
            algorithms=[alg],
            options={'verify_exp': True, 'verify_signature': True}
        )
    except PyJWTError as e:
        raise ValueError("Token verification failed") from e

    # Check expiration manually if needed
    exp = payload.get('exp')
    if exp is not None:
        if isinstance(exp, int):
            if exp < int(datetime.datetime.utcnow().timestamp()):
                raise ValueError("Token has expired")
        else:
            raise ValueError("Invalid exp claim")

    return payload
